// Create the BackoffStrategy interface here
interface BackoffStrategy {
  calculateDelay(attempt: number): number;
}

// Create the LinearBackoff class here
class LinearBackoff implements BackoffStrategy {
  baseDelay: number;
  constructor(baseDelay: number) {
    this.baseDelay = baseDelay;
  }
  calculateDelay(attempt: number): number {
    return this.baseDelay * attempt;
  }
}

// Create the ExponentialBackoff class here
class ExponentialBackoff implements BackoffStrategy {
  baseDelay: number;
  factor: number;
  constructor(baseDelay: number, factor: number) {
    this.baseDelay = baseDelay;
    this.factor = factor;
  }
  calculateDelay(attempt: number): number {
    return this.baseDelay * Math.pow(this.factor, attempt - 1);
  }
}

// Create simulateRetries function here
function simulateRetries(strategy: BackoffStrategy, maxAttempts: number): void {
  for (let i = 1; i <= maxAttempts; i++) {
    const delay = strategy.calculateDelay(i);
    console.log(`Attempt ${i}: ${delay}ms delay`);
  }
}

